import re
import os

session_dir = os.environ.get('RLM_SESSION_DIR', '')
print(f"Session dir: {session_dir}")

# Load grids from current session
jsonl_path = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')
if os.path.exists(jsonl_path):
    content = open(jsonl_path).read()
else:
    content = ""

# Find grids
pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
matches = re.finditer(pattern, content)
grids = {}
for m in matches:
    k, h, w = m[1], int(m[2]), int(m[3])
    # Extract grid rows
    text = content[m.end():].split('\n')[:h]
    grid_rows = []
    for r in text:
        if r.strip():
            grid_rows.append([int(x) for x in r.split()])
    if k not in grids:
        grids[k] = grid_rows

print("Found grids:")
for name, g in grids.items():
    print(f"  {name}: {len(g)}x{len(g[0]) if g else 0}")
    # Show first 3 rows as sample
    if g:
        print(g[:3])

