def find_bbox(grid, color):
    if color == 0:
        return None
    min_r, max_r = float('inf'), float('-inf')
    min_c, max_c = float('inf'), float('-inf')
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                min_r, max_r = min(min_r, r), max(max_r, r)
                min_c, max_c = min(min_c, c), max(max_c, c)
    return (min_r, max_r, min_c, max_c)

def transform(grid):
    colors_present = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                colors_present.add(grid[r][c])

    bboxes = []
    for color in colors_present:
        bbox = find_bbox(grid, color)
        if bbox:
            r1, r2, c1, c2 = bbox
            size_h = r2 + 1 - r1
            size_w = c2 + 1 - c1
            obj = [grid[r1 + i][c1:c1+size_w] for i in range(size_h)]
            bboxes.append((r1, obj, color))

    bboxes_sorted = sorted(bboxes, key=lambda x: x[0])

    if not bboxes_sorted:
        return grid

    result_rows = []
    max_rows = max(len(b[1]) for b in bboxes_sorted)

    for row_idx in range(max_rows):
        result_row = []
        for _, obj, _ in bboxes_sorted:
            if row_idx < len(obj):
                result_row.extend(obj[row_idx])
            else:
                result_row.extend([0] * len(obj))
        result_rows.append(result_row)

    return result_rows

